function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw salt shaker
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-20, H/2-50, 40, 50);
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2-18, H/2-48, 36, 46);

  // draw sodium particles
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(W/2-20 + Math.sin(t+i) * 10, H/2-50 + Math.cos(t+i) * 10, 2, 0, 2 * Math.PI);
    ctx.fill();
  }

  // draw pressure gauge
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2+50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2+50, H/2);
  ctx.lineTo(W/2+50 + Math.sin(t) * 20, H/2);
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2+100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+80);
  ctx.lineTo(W/2, H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2-20, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2+20, H/2+80);
  ctx.stroke();

  ctx.restore();
}
